    lights.some((light) => Array.isArray(light.color) && light.color[0] === 255 && light.color[1] === 100 && light.color[2] === 30),
    "expected fire-arrow light path to remain intact",
  );

  world.emit("spell:frost", {
    from: { x: 1, y: 1 },
    at: { x: 5, y: 1 },
